{"content":"import os, re

# Find the apiDocs code example templates — cURL example with real endpoint construction
for fn in sorted(os.listdir("/tmp/ehi_chunks")):
    if not fn.endswith(".js"):
        continue
    s = open(f"/tmp/ehi_chunks/{fn}", encoding="utf-8", errors="ignore").read()
    for pat in [r'curl ', r'-X GET', r'origin.*httpinjector', r'location\.origin', r'window\.location', r'${.*origin', r'/httpinjector', r'new URL', r'URL\(', r'searchParams']:
        for m in re.finditer(pat, s):
            i = m.start()
            ctx = s[max(0,i-120):i+220].replace("\n", " ")
            print(f"[{fn}] {pat} @ {i}: {ctx[:320]}")
            print()
            break
